// 女主角给妈妈打电话（语音，50 段）
[
  { title: "妈妈买了量子枕头", mood: { name: "量子失眠", emo: "playful", pts: 2, min: 120 },
    lines: [">我今天听讲座，买了个枕头。", "多少钱？", ">八百八，说是量子的。", "量子的枕头，和普通的差在哪？", ">它能让你同时睡着和没睡着。", "那我不是更睡不着了。", ">讲座老师说，这叫深度浅眠。"] },
  { title: "妈妈只回表情包", mood: { name: "抱拳之交", emo: "happy", pts: 2, min: 120 },
    lines: ["妈，你昨天回我的那个是什么？", ">抱拳啊，表示尊重。", "我问你吃了没，你回抱拳。", ">我吃了，也尊重你。", "那另一个流泪的猫呢？", ">那个是手滑，别当真。"] },
  { title: "妈妈替我问了AI", mood: { name: "AI红娘", emo: "playful", pts: 2, min: 150 },
    lines: [">我问那个AI，它能不能给你介绍对象。", "它怎么说？", ">它说它只是个语言模型。", "挺诚实的。", ">我又问，那能给你找房子吗？", ">它说也不能。我说那你有啥用。", "妈，你把它说沉默了吧。"] },
  { title: "家族群又99+了", mood: { name: "群里潜水", emo: "dazed", pts: 1, min: 90 },
    lines: [">你怎么不在家族群说话？", "我看了，99+，翻不动。", ">都是你三姨发的早安图。", "一百条都是早安？", ">她早上发，中午发，晚上也早安。", "那她到底几点睡？"] },
  { title: "周一就是用来熬的", mood: { name: "周一硬扛", emo: "energized", pts: 2, min: 120 },
    lines: [">今天周一，早上起得来吗？", "起是起来了，就是不太想动。", ">先吃点东西，别空着肚子。", "嗯，我去看看有什么。"] },
  { title: "妈妈要教我赚外快", mood: { name: "副业导师", emo: "confident", pts: 2, min: 150 },
    lines: [">你们年轻人是不是流行搞副业？", "对，我最近在想做什么。", ">我跳广场舞的李姐卖拖把，月入三千。", "她怎么卖的？", ">她站在舞队前面说，大家都买了。", "这个销售模式……我研究一下。"] },
  { title: "妈妈菜场砍价成功", mood: { name: "战绩辉煌", emo: "energized", pts: 3, min: 120 },
    lines: [">今天我把葱砍到八毛。", "本来多少？", ">一块。我从七点站到七点半。", "半小时省两毛？", ">省的是气势，懂不懂。", "妈，你可以去谈生意了。"] },
  { title: "妈妈要入股我的梦", mood: { name: "首位投资人", emo: "inspired", pts: 3, min: 180 },
    lines: ["妈，我想攒钱做点自己的东西。", ">做什么？", "还没想好，反正想自己做。", ">妈这有两千块养老钱，入股。", "妈，你养老钱别乱入。", ">我占的股份比你爸大，他才投了一百。"] },
  { title: "妈妈做了相亲表格", mood: { name: "表格恐惧", emo: "flirty", pts: 2, min: 120 },
    lines: [">我给你整理了个表格。", "什么表格？", ">相亲对象，年龄、工作、属相。", "还有属相？", ">还有哪个不会做饭，打叉。", "妈，那我是不是也在表格里？", ">你在最上面，打了三颗星。"] },
  { title: "妈妈说咖啡不如枸杞", mood: { name: "枸杞续命", emo: "happy", pts: 2, min: 120 },
    lines: ["妈，我今天第三杯咖啡了。", ">三杯！你那是续命还是透支？", "都有吧，不喝撑不住。", ">我给你寄枸杞，泡水喝。", "枸杞能当咖啡用吗？", ">不能，但至少你心里踏实。"] },
  { title: "妈妈要去找房东", mood: { name: "房东退避", emo: "confident", pts: 3, min: 150 },
    lines: ["妈，房东又说下个月要涨房租。", ">涨多少？", "三百。", ">我现在就订火车票，去会会他。", "别别别，我自己谈。", ">好，你谈，我在电话旁边给你壮胆。"] },
  { title: "妈妈夸我存款漂亮", mood: { name: "存款自信", emo: "happy", pts: 2, min: 120 },
    lines: [">最近存了多少？", "不多，三位数。", ">三位数也是数！", "妈，是三位数，不是六位数。", ">不是负的就是胜利。", ">你爸的存款，是我给他保管的。"] },
  { title: "妈妈替我报考公班", mood: { name: "被考公了", emo: "playful", pts: 2, min: 150 },
    lines: [">我给你报了个网课，考公的。", "您问过我了吗？", ">问了啊，我问了你的空气。", "空气没有回答吧。", ">它没反对，我就当同意。", "这套逻辑我服了。"] },
  { title: "妈妈解读体检报告", mood: { name: "报告翻译", emo: "playful", pts: 2, min: 120 },
    lines: ["妈，体检报告出来了，尿酸有点高。", ">我就知道，肯定是外卖吃的。", "还有一个箭头向上的。", ">什么箭头？", "是脂肪肝，轻度。", ">轻度也是度，明天起不许吃炸鸡。"] },
  { title: "妈妈给我朋友圈点赞", mood: { name: "头号粉丝", emo: "happy", pts: 2, min: 150 },
    lines: [">我给你朋友圈点了二十个赞。", "妈，我只发了一条。", ">我把你去年的也点了。", "你一口气翻到去年？", ">是啊，你那张吃火锅的我点了两次。", "第二次是取消再点吧。"] },
  { title: "妈妈抗议我已读不回", mood: { name: "已读回击", emo: "playful", pts: 2, min: 90 },
    lines: [">你怎么已读不回？", "我在忙，晚点回。", ">我给你发了十条语音。", "十条，我听了三条。", ">另外七条是我清嗓子的声音。", "原来如此。"] },
  { title: "妈妈给花起了我的名", mood: { name: "同名之花", emo: "happy", pts: 2, min: 150 },
    lines: [">我阳台那盆月季，叫你的名字了。", "为什么？", ">它长得慢，还总缺水。", "我哪有缺水！", ">但你们都让我操心。", "那它开花了吗？", ">开了。你呢？"] },
  { title: "爸爸学做蛋糕翻车", mood: { name: "蛋糕塌了", emo: "happy", pts: 2, min: 150 },
    lines: [">你爸今天学做蛋糕。", "他会做？", ">看了一个教程，说简单。", ">现在厨房有三个鸡蛋壳在天花板。", "天花板？怎么上去的？", ">他说是搅拌机自己跳的。"] },
  { title: "妈妈规划我的养老", mood: { name: "养老规划", emo: "confident", pts: 2, min: 150 },
    lines: [">你老了，打算住哪儿？", "妈，我才二十多岁。", ">早规划好。我看了个小区。", "您都选好了？", ">一楼带院子，种菜，你爸钓鱼。", "那我的房间呢？", ">朝南，还留着你的床。"] },
  { title: "妈妈梦见我中彩票", mood: { name: "梦里富婆", emo: "inspired", pts: 2, min: 120 },
    lines: [">我昨晚梦见你中奖了。", "多少？", ">梦里是五百万，醒来我先去买了张彩票。", "中了吗？", ">中了五块，我请你爸吃了馒头。", "这个梦的收益率还可以。"] },
  { title: "妈妈寄来二十斤红薯", mood: { name: "红薯压境", emo: "energized", pts: 2, min: 120 },
    lines: ["妈，门口堆了个大箱子。", ">是红薯，二十斤，自己种的。", "我一个人吃不完。", ">蒸、烤、煮、炸，天天换。", "那我得吃到下个月。", ">吃完了我再寄，别客气。"] },
  { title: "妈妈当上了舞队团长", mood: { name: "团长上任", emo: "inspired", pts: 3, min: 150 },
    lines: [">妈今天被选成团长了！", "恭喜！这么厉害？", ">全票通过，就是只有九个人。", "九个人也是全票。", ">我现在管着音响和领舞，还管水。", "妈，你简直是小型企业家。"] },
  { title: "妈妈说我桃花旺", mood: { name: "桃花运来", emo: "flirty", pts: 2, min: 120 },
    lines: [">我给你算了一卦。", "您什么时候会算卦了？", ">刷了半小时手机，说你今年桃花旺。", "那桃花什么时候来？", ">说是三个月内。", "妈，我是不是应该买个防桃花的口罩。"] },
  { title: "妈妈比天气预报准", mood: { name: "神准预言", emo: "playful", pts: 2, min: 90 },
    lines: [">明天降温八度，记得带伞。", "天气预报说晴天啊。", ">我的膝盖说下雨。", "膝盖比卫星还准？", ">它跟了我四十年了。", "那我明天听膝盖的。"] },
  { title: "妈妈给我分析同事", mood: { name: "同事军师", emo: "happy", pts: 2, min: 120 },
    lines: ["妈，我同事今天又偷偷吃我的零食。", ">是不是那个爱笑的？", "对，就是她。", ">这种人，你就放点辣的。", "辣的？", ">放辣条，她吃一次就不吃了。", "妈，你当年是不是搞过职场斗争。"] },
  { title: "妈妈转发香蕉谣言", mood: { name: "谣言粉碎", emo: "playful", pts: 2, min: 90 },
    lines: [">你别吃香蕉了，我刚看到说不好。", "妈，哪里说的？", ">一个群里，说得有鼻子有眼。", "那条我看了，辟谣了。", ">那我再转一条辟谣的。", "您这样群里要乱了。"] },
  { title: "妈妈远程指挥搬家", mood: { name: "搬家总指挥", emo: "energized", pts: 3, min: 150 },
    lines: ["妈，我下周要搬家了。", ">箱子怎么装？先装重的。", "我知道。", ">书放底下，锅放最上面。", "锅放最上面会砸东西的。", ">所以不能放书上面，这个我很有经验。"] },
  { title: "妈妈以为账单是奖励", mood: { name: "账单误会", emo: "happy", pts: 2, min: 120 },
    lines: ["妈，我信用卡账单到了。", ">信用卡？是不是积分换礼物那个？", "不是，这是我要还的钱。", ">那你换了个电饭煲没？", "积分还不够。", ">下个月多刷点，凑够了给妈也换一个。"] },
  { title: "妈妈教我怎么社交", mood: { name: "社交特训", emo: "confident", pts: 2, min: 150 },
    lines: [">你们楼里的邻居，认识吗？", "不认识，我怕尴尬。", ">下次电梯里，你就说“今天好冷”。", "然后呢？", ">然后他说“是啊”，这就算认识了。", "这么简单？", ">你妈我就是这么交了五十个朋友。"] },
  { title: "妈妈比我熬得还晚", mood: { name: "夜猫子妈", emo: "playful", pts: 2, min: 120 },
    lines: [">怎么还不睡？都十二点了。", "妈，你不也没睡吗？", ">我在斗地主，马上赢了。", "您说让我十一点睡的。", ">那是你，我是长辈。", "这是什么特权。"] },
  { title: "电话里听到下雨声", mood: { name: "雨夜想家", emo: "sad", pts: 2, min: 240 },
    lines: [">你那边也下雨了吧？", "嗯，今天下了一整天。", ">我这儿也是，院子里的水都漫了。", "想起小时候在屋檐下数雨滴。", ">你每次都数错。", "嗯。妈，我有点想回去。", ">那就回，门没锁。"] },
  { title: "催婚进入第三轮", mood: { name: "催婚疲劳", emo: "uncomfortable", pts: 1, min: 150 },
    lines: [">隔壁的小张下个月结婚。", "恭喜他。", ">他比你还小两岁。", "妈，咱能不聊这个吗？", ">我就是随口提一句。", "您每次都是随口提一句。", ">好好好，不提不提。"] },
  { title: "妈妈追问我的工资", mood: { name: "工资审问", emo: "tense", pts: 2, min: 120 },
    lines: [">你现在一个月到手多少？", "妈，您问这个干嘛。", ">我跟你三姨打赌呢。", "赌什么？", ">赌你能不能超过她儿子。", "你们怎么拿我打赌……"] },
  { title: "为了辞职吵了一架", mood: { name: "吵到挂断", emo: "angry", pts: 3, min: 240 },
    lines: ["妈，我想辞职，这份工作我撑不下去了。", ">辞职？你想清楚了吗？", "我加班到半夜，你根本不懂。", ">我不懂，那你说啊！", "说了你也只会说忍一忍！", ">我是怕你吃苦……", "我先挂了。"] },
  { title: "妈妈说她头晕", mood: { name: "心悬半空", emo: "scared", pts: 3, min: 180 },
    lines: [">没事，就是早上有点头晕。", "妈，你量血压了没？", ">量了，有点高。", "去医院了吗？", ">我不想麻烦你，也不想花钱。", "我现在订票回去，你先别动。"] },
  { title: "同事面前被叫小名", mood: { name: "小名公开", emo: "embarrassed", pts: 2, min: 120 },
    lines: [">喂，豆豆，吃饭了没？", "妈！我在办公室，别叫小名。", ">怎么了？这名字多可爱。", "旁边同事全听见了。", ">那我小声点，豆豆？", "……我晚点打给你。"] },
  { title: "妈妈聊了二十分钟邻居", mood: { name: "邻居连续剧", emo: "bored", pts: 1, min: 120 },
    lines: [">楼下王姨家的猫又生了。", "嗯嗯。", ">五只，两只黄的三只白的。", "哦。", ">昨天对门装修，声音大得很。", "哦。", ">你在听吗？我说到哪了？"] },
  { title: "妈妈想去西藏旅游", mood: { name: "突然远行", emo: "dazed", pts: 2, min: 120 },
    lines: [">我跟你爸商量，想去趟西藏。", "怎么突然想去西藏？", ">看了个纪录片，觉得人生不能只有菜场。", "您不是怕高原反应吗？", ">我带了二十瓶氧气。", "妈，您是认真的？", ">我买了票，下个月三号。"] },
  { title: "教妈妈用手机付款", mood: { name: "扫码教学", emo: "focused", pts: 3, min: 150 },
    lines: [">这个二维码怎么扫？", "点右上角，然后扫一扫。", ">点哪个？是这个圆的吗？", "不是，下面那个方的。", ">哦哦，出来了，要输金额吗？", "对，先输，再输密码。", ">成功了！我买到了五块钱的馒头。"] },
  { title: "老家房子要拆了", mood: { name: "老屋告别", emo: "sad", pts: 3, min: 270 },
    lines: [">跟你说件事，老屋要拆迁了。", "什么时候？", ">年底前。补偿款也谈好了。", "那我的房间呢？", ">东西我都收拾好了，你的小熊也在。", "妈，我想再回去住一晚。", ">好，这周末回来。"] },
  { title: "妈妈说我胖了", mood: { name: "体重暴击", emo: "uncomfortable", pts: 1, min: 120 },
    lines: [">我听声音，你好像胖了。", "声音还能听出胖瘦？", ">能，你说话比以前沉。", "妈，这不科学。", ">你爸也说，你嗓子都圆了。", "你们俩是联手的吧。"] },
  { title: "妈妈翻了我旧日记", mood: { name: "被翻旧账", emo: "angry", pts: 2, min: 150 },
    lines: [">我整理你房间，翻到本日记。", "你看了？", ">就翻了几页，你初中暗恋一个同学。", "妈！那是我的隐私！", ">我又没告诉别人，只告诉了你爸。", "妈！！"] },
  { title: "深夜的一通来电", mood: { name: "半夜惊魂", emo: "scared", pts: 2, min: 150 },
    lines: [">你还没睡啊？", "妈？这么晚有事吗？", ">没事，刚醒了一下，看看你睡没睡。", "我也准备睡了。您别又刷半天手机啊。"] },
  { title: "妈妈在电话里炫旧事", mood: { name: "糗事外放", emo: "embarrassed", pts: 2, min: 120 },
    lines: [">你同事在旁边吧？开免提。", "妈你要干嘛？", ">告诉她，你三岁偷穿我的高跟鞋。", "妈！我已经挂免提了。", ">那你听着，当时你还摔了个狗啃泥。", "我挂了啊！"] },
  { title: "一起挑年夜饭菜单", mood: { name: "菜单会议", emo: "focused", pts: 3, min: 150 },
    lines: [">今年年夜饭，你想吃什么？", "红烧肉、糖醋鱼，还要酸辣粉。", ">酸辣粉不算年夜饭。", "那饺子要有，要香菇馅。", ">好，我多包点，给你冻着。", "再加个鸡汤。", ">定了，十个菜，一个不少。"] },
  { title: "妈妈问我是不是失业", mood: { name: "被问失业", emo: "tense", pts: 2, min: 180 },
    lines: [">你最近怎么白天也在家？", "我……在调休。", ">调休一周了。", "公司在优化，我暂时歇着。", ">是不是被裁了？", "还没确定，我自己会处理。", ">有事别瞒着妈。"] },
  { title: "排队时给妈妈打电话", mood: { name: "排队闲聊", emo: "bored", pts: 1, min: 90 },
    lines: ["妈，我在排队，等咖啡。", ">排多久？", "前面还有十七个人。", ">那你就聊着，我也闲着。", "你今天干嘛了？", ">浇花、做饭、浇花。", "好丰富的生活。"] },
  { title: "又一年没回家过年", mood: { name: "年夜独坐", emo: "sad", pts: 3, min: 270 },
    lines: [">今年真不回来了吗？", "票抢不到，也请不下假。", ">没事，爸妈能理解。", "你们吃什么？", ">还是那些，就是桌子大了。", "我这边煮了速冻饺子。", ">那你要多吃点，我陪你。"] },
  { title: "妈妈突然说了谢谢", mood: { name: "谢谢发懵", emo: "dazed", pts: 2, min: 120 },
    lines: [">女儿，妈想跟你说句话。", "怎么了？语气这么严肃。", ">谢谢你每个月都打电话。", "妈，你怎么突然说这个？", ">我怕以后不说，就没机会了。", "你别吓我，我心跳都快了。", ">哈哈，吓你的。"] },
  { title: "妈妈让我别太惦记", mood: { name: "各自安好", emo: "sad", pts: 2, min: 180 },
    lines: [">你不用老惦记我们。", "我哪有老惦记。", ">你一周打三次电话。", "我就是想听听你的声音。", ">你好好过你的，我这边挺好的。", "嗯，我知道。", ">我也想你，就是不说。"] }
]
